import React from 'react';
import { Server, PlayCircle, HeartPulse, Gauge, Zap, AlertTriangle, Calendar, ArrowUpRight, TrendingUp } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const EnhancedKPICards = ({ summary }) => {
  const navigate = useNavigate();

  const totalAssets = summary?.totalAssets || 20;
  const running = summary?.running || 16;
  const health = 96;
  const todayProd = 14250;
  const energy = 1245;
  const alerts = summary?.highCriticality || 3;
  const maintenance = summary?.maintenance || 5;

  const cards = [
    {
      title: 'Total Assets',
      value: totalAssets,
      unit: 'Looms',
      trend: '↑ 5% this month',
      trendPositive: true,
      sub: 'Across 6 Factory Hubs',
      icon: Server,
      color: '#088395',
      route: '/assets',
    },
    {
      title: 'Running Machines',
      value: running,
      unit: `(${Math.round((running / totalAssets) * 100)}%)`,
      trend: `${Math.round((running / totalAssets) * 100)}% Operational Rate`,
      trendPositive: true,
      sub: 'Active Production Looms',
      icon: PlayCircle,
      color: '#10b981',
      route: '/assets',
    },
    {
      title: 'Machine Health Index',
      value: `${health}%`,
      unit: 'Excellent',
      trend: 'AI Risk Level: Minimal',
      trendPositive: true,
      sub: 'Predictive RUL Model Active',
      icon: HeartPulse,
      color: '#088395',
      route: '/ai-intelligence',
    },
    {
      title: "Today's Production",
      value: `${todayProd.toLocaleString()}`,
      unit: 'Meters',
      trend: 'Target: 16,000 m (89%)',
      trendPositive: true,
      sub: 'Fabric Weaving Yield',
      icon: Gauge,
      color: '#088395',
      route: '/analytics',
    },
    {
      title: 'Energy Consumption',
      value: `${energy.toLocaleString()}`,
      unit: 'kWh',
      trend: '0.42 kWh / meter rate',
      trendPositive: true,
      sub: 'Eco-Rating Grade A+',
      icon: Zap,
      color: '#7AB2B2',
      route: '/analytics',
    },
    {
      title: 'Critical Alerts',
      value: alerts,
      unit: 'Active',
      trend: 'Action Required Promptly',
      trendPositive: false,
      sub: 'High Tension & Thermal',
      icon: AlertTriangle,
      color: '#f43f5e',
      route: '/alerts',
    },
    {
      title: 'Upcoming Maintenance',
      value: maintenance,
      unit: 'Scheduled',
      trend: 'Next: LOOM-201 in 48h',
      trendPositive: true,
      sub: 'Preventive Work Orders',
      icon: Calendar,
      color: '#d97706',
      route: '/maintenance',
    },
  ];

  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(230px, 1fr))', gap: '1.1rem', marginBottom: '1.75rem' }}>
      {cards.map((c, idx) => {
        const Icon = c.icon;
        return (
          <div
            key={idx}
            onClick={() => navigate(c.route)}
            style={{
              background: 'var(--bg-card)',
              borderRadius: 'var(--radius-sm)',
              padding: '1.1rem',
              border: '1px solid var(--border-subtle)',
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              display: 'flex',
              flexDirection: 'column',
              justify: 'space-between',
              boxShadow: 'var(--shadow-card)',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-2px)';
              e.currentTarget.style.borderColor = 'var(--accent-primary)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'none';
              e.currentTarget.style.borderColor = 'var(--border-subtle)';
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.65rem' }}>
              <span style={{ fontSize: '0.78rem', fontWeight: '800', color: 'var(--text-muted)' }}>{c.title}</span>
              <div style={{ width: '32px', height: '32px', borderRadius: '6px', background: 'rgba(8, 131, 149, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: c.color }}>
                <Icon size={18} />
              </div>
            </div>

            <div>
              <div style={{ fontSize: '1.65rem', fontWeight: '900', color: 'var(--text-primary)', display: 'flex', alignItems: 'baseline', gap: '0.35rem' }}>
                {c.value}
                <span style={{ fontSize: '0.8rem', fontWeight: '700', color: 'var(--text-muted)' }}>{c.unit}</span>
              </div>
              <div style={{ fontSize: '0.74rem', color: c.trendPositive ? 'var(--status-running)' : 'var(--status-maintenance)', fontWeight: '800', marginTop: '4px', display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                <TrendingUp size={12} /> {c.trend}
              </div>
            </div>

            <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.75rem', paddingTop: '0.5rem', borderTop: '1px solid var(--border-subtle)', fontWeight: '600' }}>
              {c.sub}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default EnhancedKPICards;
